Lemma fire_0RB1LA_1RC1RD_1LA1RB_0LC0LA : forall t, ~ In t pins_0RB1LA_1RC1RD_1LA1RB_0LC0LA ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
