    exists n, (Cc (Pos.succ p)).
    split; [exact Hrun | split; [reflexivity | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->). exact (lapo_0RB1LA_1RC1RD_1LA1RB_1RC0LA p j' E).
Qed.

(** ** Bootstrap *)

Lemma boot_0RB1LA_1RC1RD_1LA1RB_1RC0LA : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
