    apply (fire_via_ovf tm Cc Hi (StC, S1)), fireo_0RB1LA_1RC1RD_1LC0LA_1RB0LA
      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 1; SWinL 3]).
    vm_compute; reflexivity.
