(** ** The lap *)

Lemma lap_0RB1LA_1RC1RD_1LC1LD_1RB0LA : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
