  apply (fire_of_run_instr tm Cc true true l B0_0RB1LA_1RC1RD_1LC1LD_1RB0LA p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_0RB1LA_1RC1RD_1LC1LD_1RB0LA p j E)].
Qed.


(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_0RB1LA_1RC1RD_1LC1LD_1RB0LA : forall t, ~ In t pins_0RB1LA_1RC1RD_1LC1LD_1RB0LA ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
