    intros p1 j1 E1.
    exact (firex_0RB1LA_1RC1RD_1LD1RB_1RB0LA [SRotL 1; SWin 1; SCycL 2 0; SWin 2] (StB, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B1 *)
    apply (fire_via_ovf tm Cc Hi (StB, S1)), fireo_0RB1LA_1RC1RD_1LD1RB_1RB0LA
      with (l := [SRotL 1; SWin 1]).
    vm_compute; reflexivity.
  - (* C0: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_0RB1LA_1RC1RD_1LD1RB_1RB0LA (StC, S0)).
    intros p1 j1 E1.
    exact (firex_0RB1LA_1RC1RD_1LD1RB_1RB0LA [SRotL 1; SWin 1; SCycL 2 0; SWin 3; SWinL 2] (StC, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* C1: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_0RB1LA_1RC1RD_1LD1RB_1RB0LA (StC, S1)).
    intros p1 j1 E1.
    exact (firex_0RB1LA_1RC1RD_1LD1RB_1RB0LA [SRotL 1; SWin 1; SCycL 2 0; SWin 3] (StC, S1) ltac:(vm_compute; reflexivity)
