    intros p1 j1 E1.
    exact (firex_0RB1LA_1RC1RD_1LD1RB_1RB0LA [SRotL 1; SWin 1; SCycL 2 0; SWin 1] (StD, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* D1 *)
    apply (fire_via_ovf tm Cc Hi (StD, S1)), fireo_0RB1LA_1RC1RD_1LD1RB_1RB0LA
