Lemma gz_0RB1LB_0LC0LC_0RD1LA_1LC1RD : forall p q0, cview p = (0, Some q0) ->
  Cc p = cden (Ap_Alph_011_111_1 q0 ++ [S0]) [] 0 Z0_0RB1LB_0LC0LC_0RD1LA_1LC1RD /\
  cden (Ap_Alph_011_111_1 q0 ++ [S0]) [] 0 Z1_0RB1LB_0LC0LC_0RD1LA_1LC1RD = Cc (Pos.succ p).
Proof.
