Lemma lapi_0RB1LB_0LC0LC_0RD1LA_1LC1RD : forall p j q0, cview p = (j, Some q0) ->
  exists n, 0 < n /\ csteps tm n (Cc p) = Some (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. destruct j as [|j'].
  - destruct (gz_0RB1LB_0LC0LC_0RD1LA_1LC1RD p q0 E) as (HA & HB).
