Definition che_0RB1LB_0LC1LC_0RD0LA_1LA1RD : list lstep := [SRotL 1; SWin 1; SCycL 3 0; SWin 2; SWinL 4; SCycR 3; SWin 1; SRotL 2; SFoldL 1].

Lemma run_exit_0RB1LB_0LC1LC_0RD0LA_1LA1RD : srun tm true true che_0RB1LB_0LC1LC_0RD0LA_1LA1RD BE0_0RB1LB_0LC1LC_0RD0LA_1LA1RD = Some (B1_0RB1LB_0LC1LC_0RD0LA_1LA1RD, 6, 8).
