(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gz_0RB1LB_0LC1LC_0RD0LA_1LA1RD : forall p q0, cview p = (0, Some q0) ->
  Cc p = cden (Ap_Alph_011_111_1 q0 ++ [S0]) [] 0 Z0_0RB1LB_0LC1LC_0RD0LA_1LA1RD /\
  cden (Ap_Alph_011_111_1 q0 ++ [S0]) [] 0 Z1_0RB1LB_0LC1LC_0RD0LA_1LA1RD = Cc (Pos.succ p).
Proof.
  intros p q0 E. destruct (Alph_011_111_1.cview_some_Alph_011_111_1 p 0 q0 E) as (H1 & H2).
  unfold Cc_0RB1LB_0LC1LC_0RD0LA_1LA1RD, cden, Z0_0RB1LB_0LC1LC_0RD0LA_1LA1RD, Z1_0RB1LB_0LC1LC_0RD0LA_1LA1RD; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  split.
  - rewrite H1; cbn [rep app]. first [ rewrite <- app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
  - rewrite H2; cbn [rep app]. first [ rewrite <- app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma gp_0RB1LB_0LC1LC_0RD0LA_1LA1RD : forall p j q0, cview p = (S j, Some q0) ->
  Cc p = cden (Ap_Alph_011_111_1 q0 ++ [S0]) [] j P0_0RB1LB_0LC1LC_0RD0LA_1LA1RD /\
  cden (Ap_Alph_011_111_1 q0 ++ [S0]) [] j P1_0RB1LB_0LC1LC_0RD0LA_1LA1RD = Cc (Pos.succ p).
