  intros p j q0 E. destruct (Alph_011_111_1.cview_some_Alph_011_111_1 p (S j) q0 E) as (H1 & H2).
  unfold Cc_0RB1LB_0LC1LC_0RD0LA_1LA1RD, cden, P0_0RB1LB_0LC1LC_0RD0LA_1LA1RD, P1_0RB1LB_0LC1LC_0RD0LA_1LA1RD; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  split.
  - rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
  - rewrite H2; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapi_0RB1LB_0LC1LC_0RD0LA_1LA1RD : forall p j q0, cview p = (j, Some q0) ->
  exists n, 0 < n /\ csteps tm n (Cc p) = Some (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. destruct j as [|j'].
  - destruct (gz_0RB1LB_0LC1LC_0RD0LA_1LA1RD p q0 E) as (HA & HB).
    exists (0 * 0 + 4). split; [lia|].
    rewrite HA.
    rewrite (srun_sound tm false true chz_0RB1LB_0LC1LC_0RD0LA_1LA1RD Z0_0RB1LB_0LC1LC_0RD0LA_1LA1RD Z1_0RB1LB_0LC1LC_0RD0LA_1LA1RD 0 4
               run_z_0RB1LB_0LC1LC_0RD0LA_1LA1RD (Ap_Alph_011_111_1 q0 ++ [S0]) [] 0
               ltac:(discriminate) ltac:(reflexivity)).
    f_equal. exact HB.
  - destruct (gp_0RB1LB_0LC1LC_0RD0LA_1LA1RD p j' q0 E) as (HA & HB).
    exists (6 * j' + 10). split; [lia|].
    rewrite HA.
    rewrite (srun_sound tm false true chp_0RB1LB_0LC1LC_0RD0LA_1LA1RD P0_0RB1LB_0LC1LC_0RD0LA_1LA1RD P1_0RB1LB_0LC1LC_0RD0LA_1LA1RD 6 10
               run_p_0RB1LB_0LC1LC_0RD0LA_1LA1RD (Ap_Alph_011_111_1 q0 ++ [S0]) [] j'
               ltac:(discriminate) ltac:(reflexivity)).
    f_equal. exact HB.
Qed.

Lemma gso_0RB1LB_0LC1LC_0RD0LA_1LA1RD : forall p j, cview p = (S j, None) ->
  Cc p = cden [] [] j B0_0RB1LB_0LC1LC_0RD0LA_1LA1RD.
