Lemma lbl_0RB1LB_0LC1LC_0RD0LA_1LA1RD : forall q l h r, lift (q,(l ++ [S0],h,r)) = lift (q,(l,h,r)).
Proof. intros. unfold lift; simpl. rewrite lift_side_app_blank. reflexivity. Qed.

Lemma geo_0RB1LB_0LC1LC_0RD0LA_1LA1RD : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_0RB1LB_0LC1LC_0RD0LA_1LA1RD) = lift (Cc (Pos.succ p)).
Proof.
  intros p j E. destruct (Alph_011_111_1.cview_none_Alph_011_111_1 p j E) as (_ & H2).
  assert (HD : cden [] [] j B1_0RB1LB_0LC1LC_0RD0LA_1LA1RD
             = (StA, (rep [S0;S1;S1] (S j) ++ [S1], S0, []))).
  { unfold cden, B1_0RB1LB_0LC1LC_0RD0LA_1LA1RD, sden, sflat;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 1) with (S j) by lia.
    replace (0 * j + 0) with 0 by lia.
    cbn [rep app]. first [ reflexivity
      | rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  assert (HC : Cc (Pos.succ p) = (StA, ((rep [S0;S1;S1] (S j) ++ [S1]) ++ [S0], S0, []))).
  { unfold Cc_0RB1LB_0LC1LC_0RD0LA_1LA1RD. rewrite H2.
    first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite !lbl_0RB1LB_0LC1LC_0RD0LA_1LA1RD. reflexivity.
Qed.

Lemma gsn_0RB1LB_0LC1LC_0RD0LA_1LA1RD : forall v i q0, cview v = (i, Some q0) ->
