(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gz_0RB1LB_0RC0LD_1LD1RC_0LA1LA : forall p q0, cview p = (0, Some q0) ->
  Cc p = cden (Ap_Alph_011_111_1 q0 ++ [S0]) [] 0 Z0_0RB1LB_0RC0LD_1LD1RC_0LA1LA /\
  lift (cden (Ap_Alph_011_111_1 q0 ++ [S0]) [] 0 Z1_0RB1LB_0RC0LD_1LD1RC_0LA1LA) = lift (Cc (Pos.succ p)).
Proof.
  intros p q0 E. destruct (Alph_011_111_1.cview_some_Alph_011_111_1 p 0 q0 E) as (H1 & H2).
  unfold Cc_0RB1LB_0RC0LD_1LD1RC_0LA1LA, cden, Z0_0RB1LB_0RC0LD_1LD1RC_0LA1LA, Z1_0RB1LB_0RC0LD_1LD1RC_0LA1LA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  split.
  - rewrite H1; cbn [rep app]. first [ rewrite <- app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
  - cbn [rep app Nat.mul Nat.add]; rewrite ?app_nil_r.
    change ([S0]) with (([]) ++ [S0]).
    rewrite !lift_app_blank.
    rewrite H2; cbn [rep app]. first [ rewrite <- app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma gp_0RB1LB_0RC0LD_1LD1RC_0LA1LA : forall p j q0, cview p = (S j, Some q0) ->
  Cc p = cden (Ap_Alph_011_111_1 q0 ++ [S0]) [] j P0_0RB1LB_0RC0LD_1LD1RC_0LA1LA /\
  lift (cden (Ap_Alph_011_111_1 q0 ++ [S0]) [] j P1_0RB1LB_0RC0LD_1LD1RC_0LA1LA) = lift (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. destruct (Alph_011_111_1.cview_some_Alph_011_111_1 p (S j) q0 E) as (H1 & H2).
  unfold Cc_0RB1LB_0RC0LD_1LD1RC_0LA1LA, cden, P0_0RB1LB_0RC0LD_1LD1RC_0LA1LA, P1_0RB1LB_0RC0LD_1LD1RC_0LA1LA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  split.
  - rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
  - cbn [rep app Nat.mul Nat.add]; rewrite ?app_nil_r.
    change ([S0]) with (([]) ++ [S0]).
    rewrite !lift_app_blank.
    rewrite H2; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapi_0RB1LB_0RC0LD_1LD1RC_0LA1LA : forall p j q0, cview p = (j, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cc p) = Some c'
               /\ lift c' = lift (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. destruct j as [|j'].
  - destruct (gz_0RB1LB_0RC0LD_1LD1RC_0LA1LA p q0 E) as (HA & HB).
    exists (0 * 0 + 4), (cden (Ap_Alph_011_111_1 q0 ++ [S0]) [] 0 Z1_0RB1LB_0RC0LD_1LD1RC_0LA1LA).
    split; [lia|]. split; [| exact HB].
    rewrite HA.
    exact (srun_sound tm false true chz_0RB1LB_0RC0LD_1LD1RC_0LA1LA Z0_0RB1LB_0RC0LD_1LD1RC_0LA1LA Z1_0RB1LB_0RC0LD_1LD1RC_0LA1LA 0 4
             run_z_0RB1LB_0RC0LD_1LD1RC_0LA1LA (Ap_Alph_011_111_1 q0 ++ [S0]) [] 0
             ltac:(discriminate) ltac:(reflexivity)).
  - destruct (gp_0RB1LB_0RC0LD_1LD1RC_0LA1LA p j' q0 E) as (HA & HB).
    exists (6 * j' + 10), (cden (Ap_Alph_011_111_1 q0 ++ [S0]) [] j' P1_0RB1LB_0RC0LD_1LD1RC_0LA1LA).
    split; [lia|]. split; [| exact HB].
    rewrite HA.
    exact (srun_sound tm false true chp_0RB1LB_0RC0LD_1LD1RC_0LA1LA P0_0RB1LB_0RC0LD_1LD1RC_0LA1LA P1_0RB1LB_0RC0LD_1LD1RC_0LA1LA 6 10
             run_p_0RB1LB_0RC0LD_1LD1RC_0LA1LA (Ap_Alph_011_111_1 q0 ++ [S0]) [] j'
             ltac:(discriminate) ltac:(reflexivity)).
Qed.

Lemma gso_0RB1LB_0RC0LD_1LD1RC_0LA1LA : forall p j, cview p = (S j, None) ->
  Cc p = cden [] [] j B0_0RB1LB_0RC0LD_1LD1RC_0LA1LA.
Proof.
  intros p j E. destruct (Alph_011_111_1.cview_none_Alph_011_111_1 p j E) as (H1 & _).
  unfold Cc_0RB1LB_0RC0LD_1LD1RC_0LA1LA, cden, B0_0RB1LB_0RC0LD_1LD1RC_0LA1LA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with (j) by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lbl_0RB1LB_0RC0LD_1LD1RC_0LA1LA : forall q l h r, lift (q,(l ++ [S0],h,r)) = lift (q,(l,h,r)).
Proof. intros. unfold lift; simpl. rewrite lift_side_app_blank. reflexivity. Qed.

Lemma geo_0RB1LB_0RC0LD_1LD1RC_0LA1LA : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_0RB1LB_0RC0LD_1LD1RC_0LA1LA) = lift (Cc (Pos.succ p)).
Proof.
  intros p j E. destruct (Alph_011_111_1.cview_none_Alph_011_111_1 p j E) as (_ & H2).
  assert (HD : cden [] [] j B1_0RB1LB_0RC0LD_1LD1RC_0LA1LA
             = (StD, (rep [S0;S1;S1] (S j) ++ [S1], S0, []))).
  { unfold cden, B1_0RB1LB_0RC0LD_1LD1RC_0LA1LA, sden, sflat;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 1) with (S j) by lia.
    replace (0 * j + 0) with 0 by lia.
    cbn [rep app]. first [ reflexivity
      | rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  assert (HC : Cc (Pos.succ p) = (StD, ((rep [S0;S1;S1] (S j) ++ [S1]) ++ [S0], S0, []))).
  { unfold Cc_0RB1LB_0RC0LD_1LD1RC_0LA1LA. rewrite H2.
    first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite !lbl_0RB1LB_0RC0LD_1LD1RC_0LA1LA. reflexivity.
Qed.

Lemma gsn_0RB1LB_0RC0LD_1LD1RC_0LA1LA : forall v i q0, cview v = (i, Some q0) ->
  Cin v = cden (Ap_Alph_101_111_1 q0 ++ [S1]) [] i AI0_0RB1LB_0RC0LD_1LD1RC_0LA1LA.
