  intros v i q0 E. destruct (Alph_101_111_1.cview_some_Alph_101_111_1 v i q0 E) as (H1 & _).
  unfold Cin_0RB1LB_0RC0LD_1LD1RC_0LA1LA, cden, AI0_0RB1LB_0RC0LD_1LD1RC_0LA1LA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * i + 0) with i by lia.
  rewrite H1. first [ rewrite <- (app_assoc (rep [S1;S1;S1] i)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma gen_0RB1LB_0RC0LD_1LD1RC_0LA1LA : forall v i q0, cview v = (i, Some q0) ->
  lift (cden (Ap_Alph_101_111_1 q0 ++ [S1]) [] i AI1_0RB1LB_0RC0LD_1LD1RC_0LA1LA) = lift (Cin (Pos.succ v)).
Proof.
  intros v i q0 E. destruct (Alph_101_111_1.cview_some_Alph_101_111_1 v i q0 E) as (_ & H2).
  unfold Cin_0RB1LB_0RC0LD_1LD1RC_0LA1LA, cden, AI1_0RB1LB_0RC0LD_1LD1RC_0LA1LA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
