  rewrite !lift_app_blank.
  rewrite H2. first [ rewrite <- (app_assoc (rep [S1;S0;S1] i)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapin_0RB1LB_0RC0LD_1LD1RC_0LA1LA : forall v i q0, cview v = (i, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cin v) = Some c'
               /\ lift c' = lift (Cin (Pos.succ v)).
Proof.
  intros v i q0 E.
  exists (6 * i + 12), (cden (Ap_Alph_101_111_1 q0 ++ [S1]) [] i AI1_0RB1LB_0RC0LD_1LD1RC_0LA1LA).
  split; [lia|]. split; [| exact (gen_0RB1LB_0RC0LD_1LD1RC_0LA1LA v i q0 E)].
  rewrite (gsn_0RB1LB_0RC0LD_1LD1RC_0LA1LA v i q0 E).
  exact (srun_sound tm false true chn_0RB1LB_0RC0LD_1LD1RC_0LA1LA AI0_0RB1LB_0RC0LD_1LD1RC_0LA1LA AI1_0RB1LB_0RC0LD_1LD1RC_0LA1LA 6 12
           run_inner_0RB1LB_0RC0LD_1LD1RC_0LA1LA (Ap_Alph_101_111_1 q0 ++ [S1]) [] i
           ltac:(discriminate) ltac:(reflexivity)).
Qed.

(** The chain into this family lands on its anchor up to 0/1
    trailing blanks. *)
Lemma gbo_0RB1LB_0RC0LD_1LD1RC_0LA1LA : forall j, lift (cden [] [] j BB1_0RB1LB_0RC0LD_1LD1RC_0LA1LA) = lift (Cin (pow2 j)).
Proof.
  intro j.
  assert (HD : cden [] [] j BB1_0RB1LB_0RC0LD_1LD1RC_0LA1LA = (StA, (rep [S1;S0;S1] j ++ [S1;S1], S0, ([]) ++ [S0]))).
  { unfold cden, BB1_0RB1LB_0RC0LD_1LD1RC_0LA1LA, sden;
