Definition mk_0RB1LB_0RC0LD_1LD1RC_0RC1LA (w : Sym) (d : Dir) (n : St) : option Trans := Some (mkTrans w d n).
Local Notation mk := mk_0RB1LB_0RC0LD_1LD1RC_0RC1LA.

(** 0RB1LB_0RC0LD_1LD1RC_0RC1LA *)
(** 0RB1LB_0RC0LD_1LD1RC_0RC1LA -- the real machine (its counter grows RIGHT). *)
Definition tm_0RB1LB_0RC0LD_1LD1RC_0RC1LA : TM := fun q s => match q, s with
  | StA, S0 => mk S0 DR StB | StA, S1 => mk S1 DL StB
  | StB, S0 => mk S0 DR StC | StB, S1 => mk S0 DL StD
  | StC, S0 => mk S1 DL StD | StC, S1 => mk S1 DR StC
  | StD, S0 => mk S0 DR StC | StD, S1 => mk S1 DL StA end.

(** Its mirror 0LB1RB_0LC0RD_1RD1LC_0LC1RA: the same counter grown leftward.  Every
    lemma below runs on the MIRRORED table;
    [Mirror.mirror_never_qh] transfers the conclusion back. *)
Definition tmm_0RB1LB_0RC0LD_1LD1RC_0RC1LA : TM := fun q s => match q, s with
  | StA, S0 => mk S0 DL StB | StA, S1 => mk S1 DR StB
  | StB, S0 => mk S0 DL StC | StB, S1 => mk S0 DR StD
  | StC, S0 => mk S1 DR StD | StC, S1 => mk S1 DL StC
  | StD, S0 => mk S0 DL StC | StD, S1 => mk S1 DR StA end.
(** the instructions the certificate claims NEVER fire; the lap
    argument runs on the machine WRAPPED at them
    ([WrapTr.tm_wrap_trs]), so a pinned instruction firing would
    halt it and every [srun] below would fail. *)
Definition pins_0RB1LB_0RC0LD_1LD1RC_0RC1LA : list Instr := [].
Definition tmw_0RB1LB_0RC0LD_1LD1RC_0RC1LA : TM := tm_wrap_trs tmm_0RB1LB_0RC0LD_1LD1RC_0RC1LA pins_0RB1LB_0RC0LD_1LD1RC_0RC1LA.
Local Notation tm := tmw_0RB1LB_0RC0LD_1LD1RC_0RC1LA.

Lemma mirror_ok_0RB1LB_0RC0LD_1LD1RC_0RC1LA : mirror_tm tm_0RB1LB_0RC0LD_1LD1RC_0RC1LA = tmm_0RB1LB_0RC0LD_1LD1RC_0RC1LA.
Proof.
  apply functional_extensionality; intro q;
    apply functional_extensionality; intro b; destruct q, b; reflexivity.
Qed.

