Lemma gen_0RB1LB_0RC0LD_1LD1RC_0RC1LA : forall v i q0, cview v = (i, Some q0) ->
  lift (cden (Ap_Alph_110_111_1 q0 ++ [S1;S1]) [] i AI1_0RB1LB_0RC0LD_1LD1RC_0RC1LA) = lift (Cin (Pos.succ v)).
Proof.
  intros v i q0 E. destruct (Alph_110_111_1.cview_some_Alph_110_111_1 v i q0 E) as (_ & H2).
  unfold Cin_0RB1LB_0RC0LD_1LD1RC_0RC1LA, cden, AI1_0RB1LB_0RC0LD_1LD1RC_0RC1LA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
