Lemma lapin_0RB1LB_0RC0LD_1LD1RC_0RC1LA : forall v i q0, cview v = (i, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cin v) = Some c'
               /\ lift c' = lift (Cin (Pos.succ v)).
Proof.
  intros v i q0 E.
  exists (6 * i + 6), (cden (Ap_Alph_110_111_1 q0 ++ [S1;S1]) [] i AI1_0RB1LB_0RC0LD_1LD1RC_0RC1LA).
  split; [lia|]. split; [| exact (gen_0RB1LB_0RC0LD_1LD1RC_0RC1LA v i q0 E)].
  rewrite (gsn_0RB1LB_0RC0LD_1LD1RC_0RC1LA v i q0 E).
  exact (srun_sound tm false true chn_0RB1LB_0RC0LD_1LD1RC_0RC1LA AI0_0RB1LB_0RC0LD_1LD1RC_0RC1LA AI1_0RB1LB_0RC0LD_1LD1RC_0RC1LA 6 6
           run_inner_0RB1LB_0RC0LD_1LD1RC_0RC1LA (Ap_Alph_110_111_1 q0 ++ [S1;S1]) [] i
           ltac:(discriminate) ltac:(reflexivity)).
Qed.

(** The chain into this family lands on its anchor up to 0/0
    trailing blanks. *)
Lemma gbo_0RB1LB_0RC0LD_1LD1RC_0RC1LA : forall j, lift (cden [] [] j BB1_0RB1LB_0RC0LD_1LD1RC_0RC1LA) = lift (Cin (pow2 j)).
Proof.
  intro j.
  assert (HD : cden [] [] j BB1_0RB1LB_0RC0LD_1LD1RC_0RC1LA = (StB, (rep [S1;S1;S0] j ++ [S1;S1;S1], S0, []))).
  { unfold cden, BB1_0RB1LB_0RC0LD_1LD1RC_0RC1LA, sden;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 0) with j by lia.
    cbn [rep app]. rewrite <- ?app_assoc. cbn [app]. rewrite ?app_nil_r.
    reflexivity. }
  assert (HC : Cin (pow2 j) = (StB, (rep [S1;S1;S0] j ++ [S1;S1;S1], S0, []))).
  { unfold Cin_0RB1LB_0RC0LD_1LD1RC_0RC1LA. rewrite epow2_0RB1LB_0RC0LD_1LD1RC_0RC1LA.
    first [ rewrite <- app_assoc; reflexivity
          | rewrite ?app_nil_r; reflexivity
          | cbn [app]; rewrite <- ?app_assoc; cbn [app];
            rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite ?lbl_0RB1LB_0RC0LD_1LD1RC_0RC1LA. rewrite ?lift_app_blank. reflexivity.
Qed.

(** This family's all-ones fill IS the next chain's start.  [cview (fill
    (pow2 j)) = (S j, None)] ([NestedLapLift.cview_fill_pow2]), so the
    family's own overflow decomposition names the word. *)
Lemma gxi_0RB1LB_0RC0LD_1LD1RC_0RC1LA : forall j, Cin (fill (pow2 j)) = cden [] [] j BM0_0RB1LB_0RC0LD_1LD1RC_0RC1LA.
Proof.
  intro j.
  destruct (Alph_110_111_1.cview_none_Alph_110_111_1 (fill (pow2 j)) j (cview_fill_pow2 j)) as (H1 & _).
  unfold Cin_0RB1LB_0RC0LD_1LD1RC_0RC1LA, cden, BM0_0RB1LB_0RC0LD_1LD1RC_0RC1LA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  replace (0 * j + 0) with 0 by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- ?app_assoc; cbn [app];
        rewrite ?app_nil_r; reflexivity | reflexivity ].
Qed.

