Lemma gen2_0RB1LB_0RC0LD_1LD1RC_0RC1LA : forall v i q0, cview v = (i, Some q0) ->
  lift (cden (Ap_Alph_110_111_1 q0 ++ [S1;S1]) [] i AI21_0RB1LB_0RC0LD_1LD1RC_0RC1LA) = lift (Cin2 (Pos.succ v)).
