Definition mk_0RB1LB_1LA0LC_0RD1LA_1LC1RD (w : Sym) (d : Dir) (n : St) : option Trans := Some (mkTrans w d n).
Local Notation mk := mk_0RB1LB_1LA0LC_0RD1LA_1LC1RD.

(** 0RB1LB_1LA0LC_0RD1LA_1LC1RD *)
(** 0RB1LB_1LA0LC_0RD1LA_1LC1RD -- the real machine (its counter grows RIGHT). *)
Definition tm_0RB1LB_1LA0LC_0RD1LA_1LC1RD : TM := fun q s => match q, s with
  | StA, S0 => mk S0 DR StB | StA, S1 => mk S1 DL StB
  | StB, S0 => mk S1 DL StA | StB, S1 => mk S0 DL StC
  | StC, S0 => mk S0 DR StD | StC, S1 => mk S1 DL StA
  | StD, S0 => mk S1 DL StC | StD, S1 => mk S1 DR StD end.

(** Its mirror 0LB1RB_1RA0RC_0LD1RA_1RC1LD: the same counter grown leftward.  Every
    lemma below runs on the MIRRORED table;
    [Mirror.mirror_never_qh] transfers the conclusion back. *)
Definition tmm_0RB1LB_1LA0LC_0RD1LA_1LC1RD : TM := fun q s => match q, s with
  | StA, S0 => mk S0 DL StB | StA, S1 => mk S1 DR StB
  | StB, S0 => mk S1 DR StA | StB, S1 => mk S0 DR StC
  | StC, S0 => mk S0 DL StD | StC, S1 => mk S1 DR StA
  | StD, S0 => mk S1 DR StC | StD, S1 => mk S1 DL StD end.
(** the instructions the certificate claims NEVER fire; the lap
    argument runs on the machine WRAPPED at them
    ([WrapTr.tm_wrap_trs]), so a pinned instruction firing would
    halt it and every [srun] below would fail. *)
Definition pins_0RB1LB_1LA0LC_0RD1LA_1LC1RD : list Instr := [].
Definition tmw_0RB1LB_1LA0LC_0RD1LA_1LC1RD : TM := tm_wrap_trs tmm_0RB1LB_1LA0LC_0RD1LA_1LC1RD pins_0RB1LB_1LA0LC_0RD1LA_1LC1RD.
Local Notation tm := tmw_0RB1LB_1LA0LC_0RD1LA_1LC1RD.

Lemma mirror_ok_0RB1LB_1LA0LC_0RD1LA_1LC1RD : mirror_tm tm_0RB1LB_1LA0LC_0RD1LA_1LC1RD = tmm_0RB1LB_1LA0LC_0RD1LA_1LC1RD.
Proof.
  apply functional_extensionality; intro q;
    apply functional_extensionality; intro b; destruct q, b; reflexivity.
Qed.

