(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gz_0RB1LB_1LA0LC_0RD1LA_1LC1RD : forall p q0, cview p = (0, Some q0) ->
  Cc p = cden (Ap_Alph_011_111_1 q0 ++ [S0]) [] 0 Z0_0RB1LB_1LA0LC_0RD1LA_1LC1RD /\
  cden (Ap_Alph_011_111_1 q0 ++ [S0]) [] 0 Z1_0RB1LB_1LA0LC_0RD1LA_1LC1RD = Cc (Pos.succ p).
Proof.
  intros p q0 E. destruct (Alph_011_111_1.cview_some_Alph_011_111_1 p 0 q0 E) as (H1 & H2).
  unfold Cc_0RB1LB_1LA0LC_0RD1LA_1LC1RD, cden, Z0_0RB1LB_1LA0LC_0RD1LA_1LC1RD, Z1_0RB1LB_1LA0LC_0RD1LA_1LC1RD; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  split.
  - rewrite H1; cbn [rep app]. first [ rewrite <- app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
  - rewrite H2; cbn [rep app]. first [ rewrite <- app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma gp_0RB1LB_1LA0LC_0RD1LA_1LC1RD : forall p j q0, cview p = (S j, Some q0) ->
  Cc p = cden (Ap_Alph_011_111_1 q0 ++ [S0]) [] j P0_0RB1LB_1LA0LC_0RD1LA_1LC1RD /\
  cden (Ap_Alph_011_111_1 q0 ++ [S0]) [] j P1_0RB1LB_1LA0LC_0RD1LA_1LC1RD = Cc (Pos.succ p).
Proof.
  intros p j q0 E. destruct (Alph_011_111_1.cview_some_Alph_011_111_1 p (S j) q0 E) as (H1 & H2).
  unfold Cc_0RB1LB_1LA0LC_0RD1LA_1LC1RD, cden, P0_0RB1LB_1LA0LC_0RD1LA_1LC1RD, P1_0RB1LB_1LA0LC_0RD1LA_1LC1RD; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  split.
  - rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
  - rewrite H2; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapi_0RB1LB_1LA0LC_0RD1LA_1LC1RD : forall p j q0, cview p = (j, Some q0) ->
  exists n, 0 < n /\ csteps tm n (Cc p) = Some (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. destruct j as [|j'].
  - destruct (gz_0RB1LB_1LA0LC_0RD1LA_1LC1RD p q0 E) as (HA & HB).
    exists (0 * 0 + 2). split; [lia|].
    rewrite HA.
    rewrite (srun_sound tm false true chz_0RB1LB_1LA0LC_0RD1LA_1LC1RD Z0_0RB1LB_1LA0LC_0RD1LA_1LC1RD Z1_0RB1LB_1LA0LC_0RD1LA_1LC1RD 0 2
               run_z_0RB1LB_1LA0LC_0RD1LA_1LC1RD (Ap_Alph_011_111_1 q0 ++ [S0]) [] 0
               ltac:(discriminate) ltac:(reflexivity)).
    f_equal. exact HB.
  - destruct (gp_0RB1LB_1LA0LC_0RD1LA_1LC1RD p j' q0 E) as (HA & HB).
    exists (6 * j' + 8). split; [lia|].
    rewrite HA.
    rewrite (srun_sound tm false true chp_0RB1LB_1LA0LC_0RD1LA_1LC1RD P0_0RB1LB_1LA0LC_0RD1LA_1LC1RD P1_0RB1LB_1LA0LC_0RD1LA_1LC1RD 6 8
               run_p_0RB1LB_1LA0LC_0RD1LA_1LC1RD (Ap_Alph_011_111_1 q0 ++ [S0]) [] j'
               ltac:(discriminate) ltac:(reflexivity)).
    f_equal. exact HB.
Qed.

Lemma gso_0RB1LB_1LA0LC_0RD1LA_1LC1RD : forall p j, cview p = (S j, None) ->
  Cc p = cden [] [] j B0_0RB1LB_1LA0LC_0RD1LA_1LC1RD.
Proof.
  intros p j E. destruct (Alph_011_111_1.cview_none_Alph_011_111_1 p j E) as (H1 & _).
  unfold Cc_0RB1LB_1LA0LC_0RD1LA_1LC1RD, cden, B0_0RB1LB_1LA0LC_0RD1LA_1LC1RD; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with (j) by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lbl_0RB1LB_1LA0LC_0RD1LA_1LC1RD : forall q l h r, lift (q,(l ++ [S0],h,r)) = lift (q,(l,h,r)).
Proof. intros. unfold lift; simpl. rewrite lift_side_app_blank. reflexivity. Qed.

Lemma geo_0RB1LB_1LA0LC_0RD1LA_1LC1RD : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_0RB1LB_1LA0LC_0RD1LA_1LC1RD) = lift (Cc (Pos.succ p)).
Proof.
  intros p j E. destruct (Alph_011_111_1.cview_none_Alph_011_111_1 p j E) as (_ & H2).
  assert (HD : cden [] [] j B1_0RB1LB_1LA0LC_0RD1LA_1LC1RD
             = (StC, (rep [S0;S1;S1] (S j) ++ [S1], S0, []))).
  { unfold cden, B1_0RB1LB_1LA0LC_0RD1LA_1LC1RD, sden, sflat;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 1) with (S j) by lia.
    replace (0 * j + 0) with 0 by lia.
    cbn [rep app]. first [ reflexivity
      | rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  assert (HC : Cc (Pos.succ p) = (StC, ((rep [S0;S1;S1] (S j) ++ [S1]) ++ [S0], S0, []))).
  { unfold Cc_0RB1LB_1LA0LC_0RD1LA_1LC1RD. rewrite H2.
    first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite !lbl_0RB1LB_1LA0LC_0RD1LA_1LC1RD. reflexivity.
Qed.

Lemma gsn_0RB1LB_1LA0LC_0RD1LA_1LC1RD : forall v i q0, cview v = (i, Some q0) ->
  Cin v = cden (Ap_Alph_101_111_1 q0 ++ [S1]) [] i AI0_0RB1LB_1LA0LC_0RD1LA_1LC1RD.
