Lemma gen_0RB1LB_1LA0LC_0RD1LA_1LC1RD : forall v i q0, cview v = (i, Some q0) ->
  lift (cden (Ap_Alph_101_111_1 q0 ++ [S1]) [] i AI1_0RB1LB_1LA0LC_0RD1LA_1LC1RD) = lift (Cin (Pos.succ v)).
