Lemma lapin_0RB1LB_1LA0LC_0RD1LA_1LC1RD : forall v i q0, cview v = (i, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cin v) = Some c'
               /\ lift c' = lift (Cin (Pos.succ v)).
Proof.
  intros v i q0 E.
  exists (6 * i + 8), (cden (Ap_Alph_101_111_1 q0 ++ [S1]) [] i AI1_0RB1LB_1LA0LC_0RD1LA_1LC1RD).
  split; [lia|]. split; [| exact (gen_0RB1LB_1LA0LC_0RD1LA_1LC1RD v i q0 E)].
  rewrite (gsn_0RB1LB_1LA0LC_0RD1LA_1LC1RD v i q0 E).
  exact (srun_sound tm false true chn_0RB1LB_1LA0LC_0RD1LA_1LC1RD AI0_0RB1LB_1LA0LC_0RD1LA_1LC1RD AI1_0RB1LB_1LA0LC_0RD1LA_1LC1RD 6 8
           run_inner_0RB1LB_1LA0LC_0RD1LA_1LC1RD (Ap_Alph_101_111_1 q0 ++ [S1]) [] i
           ltac:(discriminate) ltac:(reflexivity)).
