Definition A1_0RB1LB_1LA1RC_1LA1RD_0RC0LA : sconf := mkC StB (mkS [] [S1;S1] 1 0 [S1;S0]) S0 (mkS [S1;S1] [] 0 0 []).
Definition chi_0RB1LB_1LA1RC_1LA1RD_0RC0LA : list lstep := [SWin 8; SCycL 2 0; SWin 4; SCycR 2].

Lemma run_int_0RB1LB_1LA1RC_1LA1RD_0RC0LA : srun tm false true chi_0RB1LB_1LA1RC_1LA1RD_0RC0LA A0_0RB1LB_1LA1RC_1LA1RD_0RC0LA = Some (A1_0RB1LB_1LA1RC_1LA1RD_0RC0LA, 4, 12).
