(** ** The INNER anchor family -- Jp at StB *)
Definition Cin_0RB1LB_1LA1RC_1LA1RD_0RC0LA (v : positive) : cconf := (StB, (Jp v ++ [], S0, [S1;S1])).
Local Notation Cin := Cin_0RB1LB_1LA1RC_1LA1RD_0RC0LA.

(** [E (2^n) = A^n C]: the value this family's count starts at. *)
Lemma epow2_0RB1LB_1LA1RC_1LA1RD_0RC0LA : forall n, Jp (pow2 n) = rep [S1;S1] n ++ [S1].
Proof. induction n; simpl; [reflexivity | rewrite IHn; reflexivity]. Qed.

(** Its own INTERIOR lap -- ordinary and affine.  Iterating it to the fill is
    where a [Theta(2^j)] lives, and [inner_to_fill_lift] keeps it inside an
    existential. *)
Definition AI0_0RB1LB_1LA1RC_1LA1RD_0RC0LA : sconf := mkC StB (mkS [] [S1;S0] 1 0 [S1;S1]) S0 (mkS [S1;S1] [] 0 0 []).
Definition AI1_0RB1LB_1LA1RC_1LA1RD_0RC0LA : sconf := mkC StB (mkS [] [S1;S1] 1 0 [S1;S0]) S0 (mkS [S1;S1] [] 0 0 []).
Definition chn_0RB1LB_1LA1RC_1LA1RD_0RC0LA : list lstep := [SWin 8; SCycL 2 0; SWin 4; SCycR 2].

Lemma run_inner_0RB1LB_1LA1RC_1LA1RD_0RC0LA : srun tm false true chn_0RB1LB_1LA1RC_1LA1RD_0RC0LA AI0_0RB1LB_1LA1RC_1LA1RD_0RC0LA = Some (AI1_0RB1LB_1LA1RC_1LA1RD_0RC0LA, 4, 12).
Proof. vm_compute. reflexivity. Qed.

(** *** boot: the outer overflow anchor -> the first inner anchor at [pow2 j] *)
Definition BB1_0RB1LB_1LA1RC_1LA1RD_0RC0LA : sconf := mkC StB (mkS [] [S1;S1] 1 0 [S1;S0;S0]) S0 (mkS [S1;S1] [] 0 0 []).
Definition chb_0RB1LB_1LA1RC_1LA1RD_0RC0LA : list lstep := [SWin 8; SCycL 2 0; SWin 4; SCycR 2].

Lemma run_boot_0RB1LB_1LA1RC_1LA1RD_0RC0LA : srun tm true true chb_0RB1LB_1LA1RC_1LA1RD_0RC0LA B0_0RB1LB_1LA1RC_1LA1RD_0RC0LA = Some (BB1_0RB1LB_1LA1RC_1LA1RD_0RC0LA, 4, 12).
Proof. vm_compute. reflexivity. Qed.

(** *** exit: the last inner all-ones fill -> the outer successor *)
Definition BE0_0RB1LB_1LA1RC_1LA1RD_0RC0LA : sconf := mkC StB (mkS [] [S1;S0] 1 0 [S1]) S0 (mkS [S1;S1] [] 0 0 []).
Definition che_0RB1LB_1LA1RC_1LA1RD_0RC0LA : list lstep := [SWin 8; SCycL 2 0; SWin 1; SWinL 9; SCycR 2; SRotL 2; SFoldL 1].

Lemma run_exit_0RB1LB_1LA1RC_1LA1RD_0RC0LA : srun tm true true che_0RB1LB_1LA1RC_1LA1RD_0RC0LA BE0_0RB1LB_1LA1RC_1LA1RD_0RC0LA = Some (B1_0RB1LB_1LA1RC_1LA1RD_0RC0LA, 4, 18).
Proof. vm_compute. reflexivity. Qed.

(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gsi_0RB1LB_1LA1RC_1LA1RD_0RC0LA : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Jp q0 ++ [S1;S0]) [] j A0_0RB1LB_1LA1RC_1LA1RD_0RC0LA.
Proof.
  intros p j q0 E. destruct (JpCounter.cview_some_J p j q0 E) as (H1 & _).
  unfold Cc_0RB1LB_1LA1RC_1LA1RD_0RC0LA, cden, A0_0RB1LB_1LA1RC_1LA1RD_0RC0LA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  rewrite H1. first [ rewrite <- (app_assoc (rep [S1;S0] j)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma gei_0RB1LB_1LA1RC_1LA1RD_0RC0LA : forall p j q0, cview p = (j, Some q0) ->
  cden (Jp q0 ++ [S1;S0]) [] j A1_0RB1LB_1LA1RC_1LA1RD_0RC0LA = Cc (Pos.succ p).
Proof.
  intros p j q0 E. destruct (JpCounter.cview_some_J p j q0 E) as (_ & H2).
  unfold Cc_0RB1LB_1LA1RC_1LA1RD_0RC0LA, cden, A1_0RB1LB_1LA1RC_1LA1RD_0RC0LA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  rewrite H2. first [ rewrite <- (app_assoc (rep [S1;S1] j)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapi_0RB1LB_1LA1RC_1LA1RD_0RC0LA : forall p j q0, cview p = (j, Some q0) ->
  exists n, 0 < n /\ csteps tm n (Cc p) = Some (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. exists (4 * j + 12). split; [lia|].
  rewrite (gsi_0RB1LB_1LA1RC_1LA1RD_0RC0LA p j q0 E).
  rewrite (srun_sound tm false true chi_0RB1LB_1LA1RC_1LA1RD_0RC0LA A0_0RB1LB_1LA1RC_1LA1RD_0RC0LA A1_0RB1LB_1LA1RC_1LA1RD_0RC0LA 4 12
             run_int_0RB1LB_1LA1RC_1LA1RD_0RC0LA (Jp q0 ++ [S1;S0]) [] j
             ltac:(discriminate) ltac:(reflexivity)).
  f_equal. exact (gei_0RB1LB_1LA1RC_1LA1RD_0RC0LA p j q0 E).
Qed.

Lemma gso_0RB1LB_1LA1RC_1LA1RD_0RC0LA : forall p j, cview p = (S j, None) ->
  Cc p = cden [] [] j B0_0RB1LB_1LA1RC_1LA1RD_0RC0LA.
Proof.
  intros p j E. destruct (JpCounter.cview_none_J p j E) as (H1 & _).
  unfold Cc_0RB1LB_1LA1RC_1LA1RD_0RC0LA, cden, B0_0RB1LB_1LA1RC_1LA1RD_0RC0LA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with (j) by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lbl_0RB1LB_1LA1RC_1LA1RD_0RC0LA : forall q l h r, lift (q,(l ++ [S0],h,r)) = lift (q,(l,h,r)).
Proof. intros. unfold lift; simpl. rewrite lift_side_app_blank. reflexivity. Qed.

Lemma geo_0RB1LB_1LA1RC_1LA1RD_0RC0LA : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_0RB1LB_1LA1RC_1LA1RD_0RC0LA) = lift (Cc (Pos.succ p)).
Proof.
  intros p j E. destruct (JpCounter.cview_none_J p j E) as (_ & H2).
  assert (HD : cden [] [] j B1_0RB1LB_1LA1RC_1LA1RD_0RC0LA
             = (StB, (rep [S1;S1] (S j) ++ [S1;S1], S0, [S1;S1]))).
  { unfold cden, B1_0RB1LB_1LA1RC_1LA1RD_0RC0LA, sden, sflat;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 1) with (S j) by lia.
    replace (0 * j + 0) with 0 by lia.
    cbn [rep app]. first [ reflexivity
      | rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  assert (HC : Cc (Pos.succ p) = (StB, ((rep [S1;S1] (S j) ++ [S1;S1]) ++ [S0], S0, [S1;S1]))).
  { unfold Cc_0RB1LB_1LA1RC_1LA1RD_0RC0LA. rewrite H2.
    first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite !lbl_0RB1LB_1LA1RC_1LA1RD_0RC0LA. reflexivity.
Qed.

Lemma gsn_0RB1LB_1LA1RC_1LA1RD_0RC0LA : forall v i q0, cview v = (i, Some q0) ->
  Cin v = cden (Jp q0 ++ []) [] i AI0_0RB1LB_1LA1RC_1LA1RD_0RC0LA.
Proof.
  intros v i q0 E. destruct (JpCounter.cview_some_J v i q0 E) as (H1 & _).
  unfold Cin_0RB1LB_1LA1RC_1LA1RD_0RC0LA, cden, AI0_0RB1LB_1LA1RC_1LA1RD_0RC0LA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * i + 0) with i by lia.
  rewrite H1. first [ rewrite <- (app_assoc (rep [S1;S0] i)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma gen_0RB1LB_1LA1RC_1LA1RD_0RC0LA : forall v i q0, cview v = (i, Some q0) ->
  lift (cden (Jp q0 ++ []) [] i AI1_0RB1LB_1LA1RC_1LA1RD_0RC0LA) = lift (Cin (Pos.succ v)).
Proof.
  intros v i q0 E. destruct (JpCounter.cview_some_J v i q0 E) as (_ & H2).
  unfold Cin_0RB1LB_1LA1RC_1LA1RD_0RC0LA, cden, AI1_0RB1LB_1LA1RC_1LA1RD_0RC0LA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * i + 0) with i by lia.
  replace (0 * i + 0) with 0 by lia.
  cbn [rep app]. rewrite ?app_nil_r.
  rewrite H2. first [ rewrite <- (app_assoc (rep [S1;S1] i)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapin_0RB1LB_1LA1RC_1LA1RD_0RC0LA : forall v i q0, cview v = (i, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cin v) = Some c'
               /\ lift c' = lift (Cin (Pos.succ v)).
Proof.
  intros v i q0 E.
  exists (4 * i + 12), (cden (Jp q0 ++ []) [] i AI1_0RB1LB_1LA1RC_1LA1RD_0RC0LA).
  split; [lia|]. split; [| exact (gen_0RB1LB_1LA1RC_1LA1RD_0RC0LA v i q0 E)].
  rewrite (gsn_0RB1LB_1LA1RC_1LA1RD_0RC0LA v i q0 E).
  exact (srun_sound tm false true chn_0RB1LB_1LA1RC_1LA1RD_0RC0LA AI0_0RB1LB_1LA1RC_1LA1RD_0RC0LA AI1_0RB1LB_1LA1RC_1LA1RD_0RC0LA 4 12
           run_inner_0RB1LB_1LA1RC_1LA1RD_0RC0LA (Jp q0 ++ []) [] i
           ltac:(discriminate) ltac:(reflexivity)).
Qed.

(** The chain into this family lands on its anchor up to 2/0
    trailing blanks. *)
Lemma gbo_0RB1LB_1LA1RC_1LA1RD_0RC0LA : forall j, lift (cden [] [] j BB1_0RB1LB_1LA1RC_1LA1RD_0RC0LA) = lift (Cin (pow2 j)).
Proof.
  intro j.
  assert (HD : cden [] [] j BB1_0RB1LB_1LA1RC_1LA1RD_0RC0LA = (StB, (((rep [S1;S1] j ++ [S1]) ++ [S0]) ++ [S0], S0, [S1;S1]))).
  { unfold cden, BB1_0RB1LB_1LA1RC_1LA1RD_0RC0LA, sden;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 0) with j by lia.
    cbn [rep app]. rewrite <- ?app_assoc. cbn [app]. rewrite ?app_nil_r.
    reflexivity. }
  assert (HC : Cin (pow2 j) = (StB, (rep [S1;S1] j ++ [S1], S0, [S1;S1]))).
  { unfold Cin_0RB1LB_1LA1RC_1LA1RD_0RC0LA. rewrite epow2_0RB1LB_1LA1RC_1LA1RD_0RC0LA.
    first [ rewrite <- app_assoc; reflexivity
          | rewrite ?app_nil_r; reflexivity
          | cbn [app]; rewrite <- ?app_assoc; cbn [app];
            rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite ?lbl_0RB1LB_1LA1RC_1LA1RD_0RC0LA. rewrite ?lift_app_blank. reflexivity.
Qed.

(** This family's all-ones fill IS the next chain's start.  [cview (fill
    (pow2 j)) = (S j, None)] ([NestedLapLift.cview_fill_pow2]), so the
    family's own overflow decomposition names the word. *)
Lemma gxi_0RB1LB_1LA1RC_1LA1RD_0RC0LA : forall j, Cin (fill (pow2 j)) = cden [] [] j BE0_0RB1LB_1LA1RC_1LA1RD_0RC0LA.
Proof.
  intro j.
  destruct (JpCounter.cview_none_J (fill (pow2 j)) j (cview_fill_pow2 j)) as (H1 & _).
  unfold Cin_0RB1LB_1LA1RC_1LA1RD_0RC0LA, cden, BE0_0RB1LB_1LA1RC_1LA1RD_0RC0LA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  replace (0 * j + 0) with 0 by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- ?app_assoc; cbn [app];
        rewrite ?app_nil_r; reflexivity | reflexivity ].
Qed.

(** The interior lap, restated up to [lift] -- what [vis_via_ovf_lift] and
    [vis_via_fill] consume. *)
Lemma lapil_0RB1LB_1LA1RC_1LA1RD_0RC0LA : forall p j q0, cview p = (j, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cc p) = Some c'
               /\ lift c' = lift (Cc (Pos.succ p)).
Proof. intros p j q0 E. destruct (lapi_0RB1LB_1LA1RC_1LA1RD_0RC0LA p j q0 E) as (n & Hn & Hr).
  exists n, (Cc (Pos.succ p)).
  split; [exact Hn | split; [exact Hr | reflexivity]]. Qed.

(** The outer OVERFLOW branch, composed.  The exponential cost is the
    [exists n] inside [inner_to_fill_lift]; no formula for it is ever
    written. *)
Lemma lapo_0RB1LB_1LA1RC_1LA1RD_0RC0LA : forall p j, cview p = (S j, None) ->
  exists n c', csteps tm n (Cc p) = Some c'
          /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intros p j E.
  apply (nested_overflow_lift tm Cc Cin lapin_0RB1LB_1LA1RC_1LA1RD_0RC0LA p (pow2 j)).
  - exists (4 * j + 12), (cden [] [] j BB1_0RB1LB_1LA1RC_1LA1RD_0RC0LA).
    split; [lia|]. split; [| exact (gbo_0RB1LB_1LA1RC_1LA1RD_0RC0LA j)].
    rewrite (gso_0RB1LB_1LA1RC_1LA1RD_0RC0LA p j E).
    exact (srun_sound tm true true chb_0RB1LB_1LA1RC_1LA1RD_0RC0LA B0_0RB1LB_1LA1RC_1LA1RD_0RC0LA BB1_0RB1LB_1LA1RC_1LA1RD_0RC0LA 4 12
             run_boot_0RB1LB_1LA1RC_1LA1RD_0RC0LA [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - exists (4 * j + 18), (cden [] [] j B1_0RB1LB_1LA1RC_1LA1RD_0RC0LA).
    split; [| exact (geo_0RB1LB_1LA1RC_1LA1RD_0RC0LA p j E)].
    rewrite (gxi_0RB1LB_1LA1RC_1LA1RD_0RC0LA j).
    exact (srun_sound tm true true che_0RB1LB_1LA1RC_1LA1RD_0RC0LA BE0_0RB1LB_1LA1RC_1LA1RD_0RC0LA B1_0RB1LB_1LA1RC_1LA1RD_0RC0LA 4 18
             run_exit_0RB1LB_1LA1RC_1LA1RD_0RC0LA [] [] j ltac:(reflexivity) ltac:(reflexivity)).
Qed.



(** ** The lap *)

Lemma lap_0RB1LB_1LA1RC_1LA1RD_0RC0LA : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_0RB1LB_1LA1RC_1LA1RD_0RC0LA p j q0 E) as (n & Hn & Hrun).
    exists n, (Cc (Pos.succ p)).
    split; [exact Hrun | split; [reflexivity | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->). exact (lapo_0RB1LB_1LA1RC_1LA1RD_0RC0LA p j' E).
Qed.

(** ** Bootstrap *)

Lemma boot_0RB1LB_1LA1RC_1LA1RD_0RC0LA : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 20.
  assert (H : match csteps tm 20 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tm 20 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_0RB1LB_1LA1RC_1LA1RD_0RC0LA : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_0RB1LB_1LA1RC_1LA1RD_0RC0LA = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_0RB1LB_1LA1RC_1LA1RD_0RC0LA p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_0RB1LB_1LA1RC_1LA1RD_0RC0LA p j E)].
Qed.


(** An instruction firing in the EXIT chain is reached from the outer overflow
    anchor by boot + the inner counter's own laps + that prefix. *)
Lemma firex_0RB1LB_1LA1RC_1LA1RD_0RC0LA : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l BE0_0RB1LB_1LA1RC_1LA1RD_0RC0LA = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k e, stepn tm k (lift (Cc p)) = Some e /\ instr_of e = t.
Proof.
  intros l t Hst p j E.
  apply (fire_via_fill tm Cc Cin lapin_0RB1LB_1LA1RC_1LA1RD_0RC0LA t p (pow2 j)).
  - exists (4 * j + 12), (cden [] [] j BB1_0RB1LB_1LA1RC_1LA1RD_0RC0LA). split;
      [| exact (gbo_0RB1LB_1LA1RC_1LA1RD_0RC0LA j)].
    rewrite (gso_0RB1LB_1LA1RC_1LA1RD_0RC0LA p j E).
    exact (srun_sound tm true true chb_0RB1LB_1LA1RC_1LA1RD_0RC0LA B0_0RB1LB_1LA1RC_1LA1RD_0RC0LA BB1_0RB1LB_1LA1RC_1LA1RD_0RC0LA 4 12
             run_boot_0RB1LB_1LA1RC_1LA1RD_0RC0LA [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - apply (fire_lift_of_csteps tm (fun _ : positive => Cin (fill (pow2 j))) xH).
    apply (fire_of_run_instr tm (fun _ : positive => Cin (fill (pow2 j)))
                      true true l BE0_0RB1LB_1LA1RC_1LA1RD_0RC0LA xH j [] []);
      [exact Hst | reflexivity | reflexivity | exact (gxi_0RB1LB_1LA1RC_1LA1RD_0RC0LA j)].
Qed.

(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_0RB1LB_1LA1RC_1LA1RD_0RC0LA : forall t, ~ In t pins_0RB1LB_1LA1RC_1LA1RD_0RC0LA ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n, 0 < n /\ csteps tm n (Cc p0) = Some (Cc (Pos.succ p0)))
    by exact lapi_0RB1LB_1LA1RC_1LA1RD_0RC0LA.
  destruct t as [q b]; destruct q, b.
  - (* A0: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_0RB1LB_1LA1RC_1LA1RD_0RC0LA (StA, S0)).
    intros p1 j1 E1.
    exact (firex_0RB1LB_1LA1RC_1LA1RD_0RC0LA [SWin 8; SCycL 2 0; SWin 1; SWinL 3] (StA, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* A1 *)
    apply (fire_via_ovf tm Cc Hi (StA, S1)), fireo_0RB1LB_1LA1RC_1LA1RD_0RC0LA
      with (l := [SWin 1]).
    vm_compute; reflexivity.
  - (* B0 *)
    apply (fire_via_ovf tm Cc Hi (StB, S0)), fireo_0RB1LB_1LA1RC_1LA1RD_0RC0LA
      with (l := []).
    vm_compute; reflexivity.
  - (* B1 *)
    apply (fire_via_ovf tm Cc Hi (StB, S1)), fireo_0RB1LB_1LA1RC_1LA1RD_0RC0LA
