  | StA, S0 => mk S0 DL StB | StA, S1 => mk S1 DR StB
  | StB, S0 => mk S1 DR StC | StB, S1 => mk S0 DR StC
  | StC, S0 => mk S0 DL StD | StC, S1 => mk S1 DR StA
