Definition pins_0RB1LB_1LC0LC_0RD1LA_1LC1RD : list Instr := [].
Definition tmw_0RB1LB_1LC0LC_0RD1LA_1LC1RD : TM := tm_wrap_trs tmm_0RB1LB_1LC0LC_0RD1LA_1LC1RD pins_0RB1LB_1LC0LC_0RD1LA_1LC1RD.
Local Notation tm := tmw_0RB1LB_1LC0LC_0RD1LA_1LC1RD.

Lemma mirror_ok_0RB1LB_1LC0LC_0RD1LA_1LC1RD : mirror_tm tm_0RB1LB_1LC0LC_0RD1LA_1LC1RD = tmm_0RB1LB_1LC0LC_0RD1LA_1LC1RD.
Proof.
  apply functional_extensionality; intro q;
    apply functional_extensionality; intro b; destruct q, b; reflexivity.
Qed.

