Lemma geo_0RB1LB_1LC0LC_0RD1LA_1LC1RD : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_0RB1LB_1LC0LC_0RD1LA_1LC1RD) = lift (Cc (Pos.succ p)).
