(** *** exit: the last inner all-ones fill -> the outer successor *)
Definition BE0_0RB1LC_0LC0RD_1RD0LA_1RB0RB : sconf := mkC StB (mkS [] [S1;S1] 1 0 [S1;S1;S1]) S0 (mkS [] [] 0 0 []).
