    apply (fire_via_ovf tm Cc Hi (StB, S1)), fireo_0RB1LC_0LC1RD_0RD0LA_1LA1RD
      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 4; SCycR 2; SWin 2; SWin 4]).
    vm_compute; reflexivity.
  - (* C0 *)
    apply (fire_via_ovf tm Cc Hi (StC, S0)), fireo_0RB1LC_0LC1RD_0RD0LA_1LA1RD
      with (l := []).
    vm_compute; reflexivity.
  - (* C1 *)
    apply (fire_via_ovf tm Cc Hi (StC, S1)), fireo_0RB1LC_0LC1RD_0RD0LA_1LA1RD
      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 4]).
